package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Path;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

/** A background properties publication must not lose a concurrent native index-generation update. */
@Timeout(45)
class StorePropertiesConcurrentPublicationTest {
	@Test
	void inFlightSaveRetainsConcurrentTermIndexUpdate(@TempDir(cleanup = CleanupMode.NEVER) Path directory)
			throws Exception {
		CountDownLatch encoded = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		AtomicBoolean armed = new AtomicBoolean();
		StorePropertiesFileOps files = new StorePropertiesFileOps() {
			@Override
			public Path createDirectories(Path path) throws IOException {
				return NioStorePropertiesFileOps.INSTANCE.createDirectories(path);
			}

			@Override
			public void writeAndForce(Path path, byte[] bytes) throws IOException {
				NioStorePropertiesFileOps.INSTANCE.writeAndForce(path, bytes);
				if (armed.compareAndSet(true, false)) {
					encoded.countDown();
					try {
						if (!release.await(20, TimeUnit.SECONDS)) {
							throw new IOException("test did not release the encoded properties");
						}
					} catch (InterruptedException interrupted) {
						Thread.currentThread().interrupt();
						throw new IOException("test save interrupted", interrupted);
					}
				}
			}

			@Override
			public void moveAtomically(Path source, Path target) throws IOException {
				NioStorePropertiesFileOps.INSTANCE.moveAtomically(source, target);
			}

			@Override
			public void forceDirectory(Path path) throws IOException {
				NioStorePropertiesFileOps.INSTANCE.forceDirectory(path);
			}

			@Override
			public boolean deleteIfExists(Path path) throws IOException {
				return NioStorePropertiesFileOps.INSTANCE.deleteIfExists(path);
			}
		};
		StoreProperties properties = new StoreProperties(directory.toFile(), files)
				.setVersion("6").setTripleTermIndexes("spoc");
		properties.save();
		properties.setRdfTermDomainsVersion("rdf-term-domain-v6");
		armed.set(true);
		try (var workers = Executors.newFixedThreadPool(2)) {
			var save = workers.submit(properties::save);
			try {
				assertTrue(encoded.await(15, TimeUnit.SECONDS), "a real save must finish writing its encoded bytes");
				var update = workers.submit(() -> properties.setTripleTermIndexes("spoc,posc"));
				update.get(15, TimeUnit.SECONDS);
			} finally {
				release.countDown();
			}
			save.get(15, TimeUnit.SECONDS);
		}
		properties.save();
		StoreProperties reopened = new StoreProperties(directory.toFile());
		assertTrue(reopened.load());
		assertEquals("rdf-term-domain-v6", reopened.getRdfTermDomainsVersion());
		assertEquals("spoc,posc", reopened.getTripleTermIndexes(),
				"a setter that completed during an earlier save must remain dirty until persisted");
	}
}
